 * Modifica direttamente l'array di caratteri passato come argomento.
 * 
 * @param str Puntatore al buffer di caratteri contenente la stringa.
 * @return Il numero di caratteri nella stringa originale (lunghezza).
 */
int invertString(char *str) {
    if (str == NULL) {
        fprintf(stderr, "Errore: puntatore alla stringa è NULL.\n");
        return -1;
    }

    // Otteniamo la lunghezza della stringa
    size_t len = strlen(str);

    // Caso limite: stringa vuota o contenente solo il carattere '\0' iniziale
    if (len == 0) {
        return 0;
    }

    // Inizializziamo i due indici
    size_t left = 0;
    size_t right = len - 1;

    // Loop principale per lo scambio dei caratteri
    while (left < right) {
